import React, { useState } from 'react';
import Layout from '../components/Layout';
import ResultsTable from '../components/ResultsTable';
import InsightPanel from '../components/InsightPanel';
import { rankCandidates } from '../services/api';

const Dashboard = () => {
  const [lastUpload, setLastUpload] = useState(null);

  React.useEffect(() => {
    try {
      const raw = localStorage.getItem('last_upload');
      if (raw) setLastUpload(JSON.parse(raw));
    } catch (e) {
      setLastUpload(null);
    }
  }, []);
  const [cvData, setCvData] = useState(null);
  const [jdData, setJdData] = useState(null);
  const [jdText, setJdText] = useState('');
  const [cvFile, setCvFile] = useState(null);
  const [jdFile, setJdFile] = useState(null);
  const [candidates, setCandidates] = useState([]);
  const [selectedCandidate, setSelectedCandidate] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [processingStep, setProcessingStep] = useState(0);

  const handleCVChange = (e) => {
    setCvFile(e.target.files?.[0]);
    setError('');
  };

  const handleJDChange = (e) => {
    setJdFile(e.target.files?.[0]);
    setError('');
  };

  const handleCVUpload = async () => {
    if (!cvFile) {
      setError('Please select a CV file');
      return;
    }

    try {
      const formData = new FormData();
      formData.append('file', cvFile);
      const response = await fetch('http://localhost:5000/api/upload/cv', {
        method: 'POST',
        body: formData,
      });
      const data = await response.json();
      setCvData(data.data);
      setCvFile(null);
    } catch (err) {
      setError('Error uploading CV: ' + err.message);
    }
  };

  const handleJDUpload = async () => {
    if (!jdFile && !jdText) {
      setError('Please select a JD file or enter JD text');
      return;
    }

    try {
      let data;
      if (jdFile) {
        const formData = new FormData();
        formData.append('file', jdFile);
        const response = await fetch('http://localhost:5000/api/upload/jd', {
          method: 'POST',
          body: formData,
        });
        data = await response.json();
      } else {
        const response = await fetch('http://localhost:5000/api/upload/jd', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ text: jdText }),
        });
        data = await response.json();
      }
      setJdData(data.data);
      setJdFile(null);
      setJdText('');
    } catch (err) {
      setError('Error uploading JD: ' + err.message);
    }
  };

  const handleScreening = async () => {
    if (!cvData || !jdData) {
      setError('Please upload both CV and JD');
      return;
    }

    setLoading(true);
    setError('');
    setProcessingStep(1);

    try {
      const candidateData = [
        {
          id: cvData.candidate_id,
          name: cvData.candidate_name,
          email: cvData.email,
          skills: cvData.skills || [],
          summary: cvData.summary || '',
        },
      ];

      setProcessingStep(2);
      await new Promise((r) => setTimeout(r, 1000));

      setProcessingStep(3);
      await new Promise((r) => setTimeout(r, 1000));

      const response = await fetch('http://localhost:5000/api/screening/rank', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ candidates: candidateData, jd_data: jdData }),
      });
      const data = await response.json();
      const rankedCandidates = data.data?.ranked_candidates || [];
      setCandidates(rankedCandidates);

      if (rankedCandidates.length > 0) {
        setSelectedCandidate(rankedCandidates[0]);
      }
      setProcessingStep(4);
    } catch (err) {
      setError('Error during screening: ' + err.message);
    } finally {
      setLoading(false);
    }
  };

  const resetForm = () => {
    setCvData(null);
    setJdData(null);
    setCvFile(null);
    setJdFile(null);
    setJdText('');
    setCandidates([]);
    setSelectedCandidate(null);
    setError('');
    setProcessingStep(0);
  };

  return (
    <Layout title="Dashboard">
      <div className="max-w-[1200px] mx-auto px-8 py-8 grid grid-cols-12 gap-8">
        {lastUpload && (
          <div className="col-span-12">
            <section className="bg-white rounded-xl border border-slate-200 p-6 shadow-sm mb-6">
              <h3 className="font-semibold">Latest upload</h3>
              <p className="text-sm text-slate-600">{lastUpload.candidate_name || lastUpload.job_title || 'Recent upload'}</p>
              {lastUpload.summary && <p className="mt-3 text-sm text-slate-700">{lastUpload.summary}</p>}
            </section>
          </div>
        )}
        {/* Left Column: Upload & Input */}
        <div className="col-span-12 lg:col-span-8 space-y-8">
          <section className="bg-white rounded-xl border border-slate-200 p-8 shadow-sm">
            <header className="mb-8">
              <h2 className="font-h2 text-h2 text-primary">Upload CV & Screening Data</h2>
              <p className="font-body-md text-body-md text-secondary mt-2">Upload candidate files for automated AI extraction and score mapping.</p>
            </header>

            {/* Drag and Drop Box */}
            <div className="relative flex flex-col items-center justify-center border-2 border-dashed border-slate-200 rounded-xl p-8 bg-slate-50 hover:bg-slate-100/50 hover:border-primary transition-all cursor-pointer h-64 group mb-8">
              <div className="bg-white h-16 w-16 rounded-full shadow-sm flex items-center justify-center mb-4 group-hover:scale-110 transition-transform">
                <span className="material-symbols-outlined text-primary text-4xl">upload_file</span>
              </div>
              <div className="text-center">
                <p className="font-h3 text-h3 text-primary">Click or drag files to upload</p>
                <p className="font-body-md text-body-md text-secondary mt-2">Support for PDF, DOCX, and TXT (Max 25MB per file)</p>
              </div>
              <input
                type="file"
                onChange={handleCVChange}
                accept=".pdf,.docx,.doc,.txt"
                className="absolute inset-0 opacity-0 cursor-pointer"
              />
            </div>

            {cvFile && (
              <div className="mb-4 p-4 bg-green-50 border border-green-200 rounded-lg flex justify-between items-center">
                <p className="text-sm font-medium text-green-800">
                  <span className="material-symbols-outlined inline mr-2">check_circle</span>
                  {cvFile.name}
                </p>
                <button
                  onClick={handleCVUpload}
                  className="px-4 py-2 bg-primary text-white rounded-lg text-sm font-semibold hover:opacity-90"
                >
                  Upload CV
                </button>
              </div>
            )}

            {/* Job Description Input */}
            <div className="mt-8">
              <label className="font-label-sm text-label-sm text-secondary uppercase tracking-wider block mb-3">
                Job Description Requirement
              </label>
              <div className="space-y-4">
                <textarea
                  value={jdText}
                  onChange={(e) => setJdText(e.target.value)}
                  className="w-full h-40 rounded-lg border border-slate-200 bg-white p-4 font-body-md text-body-md focus:ring-2 focus:ring-primary-fixed-dim focus:border-primary outline-none resize-none transition-all"
                  placeholder="Paste job description here..."
                  spellCheck="false"
                />
                <div className="text-center text-sm text-slate-500 py-2">OR</div>
                <input
                  type="file"
                  onChange={handleJDChange}
                  accept=".pdf,.docx,.doc,.txt"
                  className="w-full p-3 border border-dashed border-slate-300 rounded-lg text-sm"
                />
              </div>

              {jdFile && (
                <div className="mt-4 p-4 bg-green-50 border border-green-200 rounded-lg flex justify-between items-center">
                  <p className="text-sm font-medium text-green-800">
                    <span className="material-symbols-outlined inline mr-2">check_circle</span>
                    {jdFile.name}
                  </p>
                  <button
                    onClick={handleJDUpload}
                    className="px-4 py-2 bg-primary text-white rounded-lg text-sm font-semibold hover:opacity-90"
                  >
                    Upload JD
                  </button>
                </div>
              )}

              {jdText && !jdFile && (
                <div className="mt-4 p-4 bg-green-50 border border-green-200 rounded-lg flex justify-between items-center">
                  <p className="text-sm font-medium text-green-800">
                    <span className="material-symbols-outlined inline mr-2">check_circle</span>
                    Job description ready
                  </p>
                  <button
                    onClick={handleJDUpload}
                    className="px-4 py-2 bg-primary text-white rounded-lg text-sm font-semibold hover:opacity-90"
                  >
                    Use JD
                  </button>
                </div>
              )}
            </div>

            {/* Actions */}
            <div className="mt-8 flex items-center justify-between gap-4 pt-8 border-t border-slate-100">
              <button
                onClick={resetForm}
                className="px-6 py-3 bg-white border border-slate-200 rounded-lg font-sans text-sm font-semibold text-slate-700 hover:bg-slate-50 transition-all flex items-center gap-2"
              >
                <span className="material-symbols-outlined text-sm">restart_alt</span>
                Reset
              </button>
              <button
                onClick={handleScreening}
                disabled={loading || !cvData || !jdData}
                className="px-8 py-3 bg-primary text-white rounded-lg font-sans text-sm font-semibold shadow-md hover:opacity-90 disabled:opacity-50 transition-all flex items-center gap-2"
              >
                <span className="material-symbols-outlined text-sm">auto_awesome</span>
                {loading ? 'Running Screening...' : 'Run AI Screening'}
              </button>
            </div>
          </section>

          {/* Results Table */}
          {candidates.length > 0 && (
            <ResultsTable candidates={candidates} onSelectCandidate={setSelectedCandidate} />
          )}
        </div>

        {/* Right Column: Status & Progress */}
        <div className="col-span-12 lg:col-span-4 space-y-8">
          {/* Status Cards */}
          <div className="space-y-4">
            <div className={`p-4 rounded-xl border transition-all ${cvData ? 'bg-green-50 border-green-300' : 'bg-gray-50 border-gray-200'}`}>
              <p className="text-sm font-semibold">
                {cvData ? `✅ CV Uploaded: ${cvData.candidate_name}` : '⏳ Awaiting CV'}
              </p>
            </div>
            <div className={`p-4 rounded-xl border transition-all ${jdData ? 'bg-green-50 border-green-300' : 'bg-gray-50 border-gray-200'}`}>
              <p className="text-sm font-semibold">
                {jdData ? `✅ JD Loaded: ${jdData.job_title}` : '⏳ Awaiting JD'}
              </p>
            </div>
          </div>

          {/* Processing Status */}
          {loading && (
            <section className="bg-white rounded-xl border border-slate-200 p-6 shadow-sm">
              <header className="flex items-center justify-between mb-6">
                <h3 className="font-h3 text-h3 text-primary">Screening Status</h3>
                <span className="px-2 py-1 bg-primary text-white text-[10px] font-bold rounded uppercase">Processing</span>
              </header>

              <div className="mb-6">
                <div className="flex justify-between items-end mb-2">
                  <p className="font-body-md text-body-md text-primary font-semibold">Processing Pipeline</p>
                  <p className="font-data-mono text-data-mono text-primary">{processingStep * 25}%</p>
                </div>
                <div className="h-2 w-full bg-slate-100 rounded-full overflow-hidden">
                  <div
                    className="h-full bg-primary rounded-full transition-all duration-500"
                    style={{ width: `${processingStep * 25}%` }}
                  />
                </div>
              </div>

              <div className="space-y-4">
                {[
                  { step: 1, title: 'Upload Complete', desc: 'CV and JD uploaded' },
                  { step: 2, title: 'Parsing CV', desc: 'Extracting CV data...' },
                  { step: 3, title: 'Matching & Scoring', desc: 'Computing similarity...' },
                  { step: 4, title: 'Results Ready', desc: 'Screening complete' },
                ].map((item, idx) => (
                  <div key={idx} className="flex gap-4">
                    <div className="flex flex-col items-center">
                      <div
                        className={`h-6 w-6 rounded-full flex items-center justify-center ${
                          processingStep > item.step
                            ? 'bg-green-100'
                            : processingStep === item.step
                            ? 'border-2 border-primary'
                            : 'bg-slate-50'
                        }`}
                      >
                        {processingStep > item.step && (
                          <span className="material-symbols-outlined text-green-600 text-sm">check</span>
                        )}
                        {processingStep === item.step && (
                          <div className="h-2 w-2 rounded-full bg-primary animate-pulse" />
                        )}
                      </div>
                      {idx < 3 && <div className="w-px h-6 bg-slate-100 mt-1" />}
                    </div>
                    <div className="pb-2">
                      <p className={`font-body-md text-body-md ${processingStep >= item.step ? 'text-primary font-semibold' : 'text-slate-400'}`}>
                        {item.title}
                      </p>
                      <p className="text-xs text-slate-500">{item.desc}</p>
                    </div>
                  </div>
                ))}
              </div>
            </section>
          )}

          {/* Results Summary */}
          {candidates.length > 0 && selectedCandidate && (
            <InsightPanel candidate={selectedCandidate} />
          )}

          {/* Pro Tip */}
          <section className="bg-primary-container text-white rounded-xl p-6 shadow-sm">
            <span className="material-symbols-outlined mb-3 block">lightbulb</span>
            <h4 className="font-h3 text-h3 mb-2">Pro Tip</h4>
            <p className="font-body-md text-body-md opacity-90 leading-relaxed">
              For better results, include specific technical keywords and experience ranges in your job description.
            </p>
          </section>

          {/* Error Display */}
          {error && (
            <div className="bg-error-container border border-error text-error px-4 py-3 rounded-lg text-sm">
              {error}
            </div>
          )}
        </div>
      </div>
    </Layout>
  );
};

export default Dashboard;
